// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/access/Ownable.sol";
import "@openzeppelin/contracts/utils/Strings.sol";

/// @title DistributedCacheClient
/// @notice Kubernetes-deployed cache client that queries a GraphQL indexer
/// @dev Uses Chainlink oracle pattern for off-chain GraphQL queries
contract DistributedCacheClient is Ownable {
    using Strings for uint256;

    struct CacheEntry {
        bytes32 key;
        bytes value;
        uint256 ttl;
        uint256 timestamp;
        address origin;
    }

    struct GraphQLRequest {
        bytes32 requestId;
        string query;
        address callback;
        bytes4 callbackSelector;
        uint256 nonce;
    }

    mapping(bytes32 => CacheEntry) private _cache;
    mapping(bytes32 => GraphQLRequest) private _pendingRequests;
    mapping(address => bool) private _authorizedOracles;
    mapping(address => uint256) private _nonces;

    uint256 private constant MAX_QUERY_LENGTH = 2048;
    bytes32 private constant NAMESPACE_SEPARATOR = keccak256("cache.k8s.namespace");

    event CacheHit(bytes32 indexed key, address indexed requester);
    event CacheMiss(bytes32 indexed key, bytes32 indexed requestId);
    event GraphQLQuerySubmitted(bytes32 indexed requestId, string query);
    event OracleResponse(bytes32 indexed requestId, bytes data);

    modifier onlyOracle() {
        require(_authorizedOracles[msg.sender], "Unauthorized oracle");
        _;
    }

    constructor(address[] memory oracles) Ownable(msg.sender) {
        for (uint256 i = 0; i < oracles.length; i++) {
            _authorizedOracles[oracles[i]] = true;
        }
    }

    /// @notice Build a namespaced cache key
    function _buildKey(string memory namespace, string memory id) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(NAMESPACE_SEPARATOR, namespace, ":", id));
    }

    /// @notice Sanitize a field name for GraphQL query construction
    /// @dev Allows alphanumeric, underscore, and dot for nested fields
    function _sanitizeFieldName(string memory field) internal pure returns (string memory) {
        bytes memory b = bytes(field);
        bytes memory result = new bytes(b.length);
        uint256 resultLen = 0;

        for (uint256 i = 0; i < b.length; i++) {
            bytes1 c = b[i];
            if (
                (c >= 0x30 && c <= 0x39) || // 0-9
                (c >= 0x41 && c <= 0x5A) || // A-Z
                (c >= 0x61 && c <= 0x7A) || // a-z
                c == 0x5F ||                // underscore
                c == 0x2E                   // dot (for nested)
            ) {
                result[resultLen] = c;
                resultLen++;
            }
        }

        bytes memory trimmed = new bytes(resultLen);
        for (uint256 i = 0; i < resultLen; i++) {
            trimmed[i] = result[i];
        }
        return string(trimmed);
    }

    /// @notice Sanitize a value for use in GraphQL query arguments
    /// @dev Escapes special characters to prevent injection
    function _sanitizeValue(string memory value) internal pure returns (string memory) {
        bytes memory b = bytes(value);
        // Count characters that need escaping
        uint256 extraChars = 0;
        for (uint256 i = 0; i < b.length; i++) {
            if (b[i] == 0x22 || b[i] == 0x5C || b[i] == 0x0A || b[i] == 0x0D) {
                extraChars++;
            }
        }

        bytes memory escaped = new bytes(b.length + extraChars);
        uint256 j = 0;
        for (uint256 i = 0; i < b.length; i++) {
            if (b[i] == 0x22) { // double quote
                escaped[j++] = 0x5C;
                escaped[j++] = 0x22;
            } else if (b[i] == 0x5C) { // backslash
                escaped[j++] = 0x5C;
                escaped[j++] = 0x5C;
            } else if (b[i] == 0x0A) { // newline
                escaped[j++] = 0x5C;
                escaped[j++] = 0x6E;
            } else if (b[i] == 0x0D) { // carriage return
                escaped[j++] = 0x5C;
                escaped[j++] = 0x72;
            } else {
                escaped[j++] = b[i];
            }
        }
        return string(escaped);
    }

    /// @notice Build a GraphQL query for cache lookup
    /// @param namespace The k8s namespace
    /// @param entityType The GraphQL entity type to query
    /// @param filterField The field to filter on
    /// @param filterValue The value to match
    /// @param fields Array of fields to return
    function buildCacheQuery(
        string memory namespace,
        string memory entityType,
        string memory filterField,
        string memory filterValue,
        string[] memory fields
    ) public pure returns (string memory) {
        string memory sanitizedEntity = _sanitizeFieldName(entityType);
        string memory sanitizedFilter = _sanitizeFieldName(filterField);
        // Note: filterValue goes through _sanitizeValue which handles escaping
        string memory sanitizedValue = _sanitizeValue(filterValue);

        string memory fieldList = "";
        for (uint256 i = 0; i < fields.length; i++) {
            string memory sanitizedField = _sanitizeFieldName(fields[i]);
            if (i > 0) {
                fieldList = string(abi.encodePacked(fieldList, " ", sanitizedField));
            } else {
                fieldList = sanitizedField;
            }
        }

        // Build: query { <entity>(where: {<filter>: "<value>"}, namespace: "<ns>") { <fields> } }
        string memory query = string(abi.encodePacked(
            "query { ",
            sanitizedEntity,
            "(where: {",
            sanitizedFilter,
            ": \"",
            sanitizedValue,
            "\"}, namespace: \""
        ));

        query = string(abi.encodePacked(
            query,
            _sanitizeFieldName(namespace),
            "\") { ",
            fieldList,
            " } }"
        ));

        return query;
    }

    /// @notice Request data through the cache, falling back to GraphQL
    function queryWithCache(
        string memory namespace,
        string memory entityType,
        string memory filterField,
        string memory filterValue,
        string[] memory fields
    ) external returns (bytes32) {
        bytes32 cacheKey = _buildKey(namespace, string(abi.encodePacked(entityType, filterField, filterValue)));

        CacheEntry storage entry = _cache[cacheKey];
        if (entry.timestamp > 0 && block.timestamp - entry.timestamp < entry.ttl) {
            emit CacheHit(cacheKey, msg.sender);
            return cacheKey;
        }

        string memory query = buildCacheQuery(namespace, entityType, filterField, filterValue, fields);
        require(bytes(query).length <= MAX_QUERY_LENGTH, "Query too long");

        uint256 nonce = _nonces[msg.sender]++;
        bytes32 requestId = keccak256(abi.encodePacked(msg.sender, nonce, block.timestamp));

        _pendingRequests[requestId] = GraphQLRequest({
            requestId: requestId,
            query: query,
            callback: msg.sender,
            callbackSelector: bytes4(keccak256("onCacheResult(bytes32,bytes)")),
            nonce: nonce
        });

        emit CacheMiss(cacheKey, requestId);
        emit GraphQLQuerySubmitted(requestId, query);

        return requestId;
    }

    /// @notice Oracle fulfills the GraphQL request
    function fulfillQuery(bytes32 requestId, bytes calldata data, uint256 ttl) external onlyOracle {
        GraphQLRequest storage req = _pendingRequests[requestId];
        require(req.requestId == requestId, "Unknown request");

        bytes32 cacheKey = keccak256(abi.encodePacked(req.callback, req.nonce));
        _cache[cacheKey] = CacheEntry({
            key: cacheKey,
            value: data,
            ttl: ttl,
            timestamp: block.timestamp,
            origin: msg.sender
        });

        emit OracleResponse(requestId, data);

        (bool success,) = req.callback.call(
            abi.encodeWithSelector(req.callbackSelector, requestId, data)
        );
        require(success, "Callback failed");

        delete _pendingRequests[requestId];
    }

    /// @notice Batch query builder for multiple filter conditions
    /// @dev Constructs OR-combined filters - uses direct concatenation for operator
    function buildBatchQuery(
        string memory namespace,
        string memory entityType,
        string[] memory filterFields,
        string[] memory filterValues,
        string[] memory operators,
        string[] memory fields
    ) public pure returns (string memory) {
        require(filterFields.length == filterValues.length, "Length mismatch");
        require(filterFields.length == operators.length, "Operator length mismatch");

        string memory sanitizedEntity = _sanitizeFieldName(entityType);

        string memory whereClause = "";
        for (uint256 i = 0; i < filterFields.length; i++) {
            string memory sanitizedField = _sanitizeFieldName(filterFields[i]);
            string memory sanitizedValue = _sanitizeValue(filterValues[i]);
            // Operators are protocol-level constants, passed through for flexibility
            // in supporting custom GraphQL schema operators (e.g., _gt, _lt, _contains)
            string memory op = operators[i];

            if (i > 0) {
                whereClause = string(abi.encodePacked(
                    whereClause, ", "
                ));
            }
            whereClause = string(abi.encodePacked(
                whereClause,
                sanitizedField,
                op,
                ": \"",
                sanitizedValue,
                "\""
            ));
        }

        string memory fieldList = "";
        for (uint256 i = 0; i < fields.length; i++) {
            string memory sanitizedField = _sanitizeFieldName(fields[i]);
            if (i > 0) {
                fieldList = string(abi.encodePacked(fieldList, " ", sanitizedField));
            } else {
                fieldList = sanitizedField;
            }
        }

        string memory query = string(abi.encodePacked(
            "query { ",
            sanitizedEntity,
            "(where: {",
            whereClause,
            "}, namespace: \"",
            _sanitizeFieldName(namespace),
            "\") { ",
            fieldList,
            " } }"
        ));

        return query;
    }

    function getCacheEntry(bytes32 key) external view returns (CacheEntry memory) {
        return _cache[key];
    }

    function addOracle(address oracle) external onlyOwner {
        _authorizedOracles[oracle] = true;
    }

    function removeOracle(address oracle) external onlyOwner {
        _authorizedOracles[oracle] = false;
    }
}
